"""The opt-in repository map: generated by whatever Python has aider, cached per commit outside
the repository, and put in context once per session -- ranked toward the first prompt where the
agent's prompt hook can carry context, at session start where it cannot."""
import os
import runpy
import stat
import subprocess
import sys
from pathlib import Path
from types import SimpleNamespace

import pytest

from tokeneconomizer.plugin import repomap
from tokeneconomizer.plugin.config import LiveConfig
from tokeneconomizer.plugin.store import Store
from tests.test_live_hooks import call, env, repo  # noqa: F401

FAKE = """#!/bin/sh
# A stand-in for a Python with aider: the import probe succeeds, and the generator prints a
# map that names the identifiers it was ranked toward.
if [ "$1" = "-c" ]; then exit {probe}; fi
if [ -n "$4" ] && [ "{slow}" = "1" ]; then sleep 3; fi
echo "pkg/core.py:"
echo "| def run(): ranked toward [$4]"
"""


def _fake(tmp_path, probe=0, slow=0):
    if os.name == "nt":
        pytest.skip("the stand-in Python is an sh script, which Windows cannot start")
    p = tmp_path / f"fakepy-{probe}-{slow}"
    p.write_text(FAKE.format(probe=probe, slow=slow))
    p.chmod(p.stat().st_mode | stat.S_IEXEC)
    return str(p)


def _env(env, tmp_path, mode="on", **kw):
    e = dict(env, TE_REPOMAP=mode, TE_REPOMAP_PYTHON=_fake(tmp_path, **kw))
    return e


def _session(e, repo, sid, prompts, host=None):
    base = {"session_id": sid, "transcript_path": "", "cwd": repo, "prompt_id": "p"}
    start = call(e, dict(base, hook_event_name="SessionStart", source="startup"), host)
    outs = [call(e, dict(base, hook_event_name="UserPromptSubmit", prompt=p,
                         prompt_id=f"p{i}"), host) for i, p in enumerate(prompts)]
    return start, outs


def _ctx_text(out):
    return (out.get("hookSpecificOutput") or {}).get("additionalContext") or out.get(
        "additionalContext") or ""


def test_repomap_takes_on_off_and_start():
    cfg = LiveConfig()
    assert cfg.repomap == "off"
    assert cfg.set("repomap", "on") and cfg.repomap == "on"
    assert cfg.set("repomap", "start") and cfg.repomap == "start"
    assert cfg.set("repomap", "false") and cfg.repomap == "off"
    assert not cfg.set("repomap", "sometimes")


def test_the_first_prompt_gets_a_map_ranked_toward_what_it_names(env, repo, tmp_path):
    e = _env(env, tmp_path)
    start, outs = _session(e, repo, "s1", ["Fix `parse_config` in ConfigLoader", "and then?"])
    assert "Repository map" not in _ctx_text(start)          # Claude Code: not at session start
    first = _ctx_text(outs[0])
    assert first.startswith("# Repository map") and "parse_config" in first
    assert "ConfigLoader" in first
    assert "added a map of acme/widget" in outs[0]["systemMessage"]
    assert _ctx_text(outs[1]) == ""                          # once per session
    _, again = _session(e, repo, "s2", ["Fix `other_thing`"])
    assert "other_thing" in _ctx_text(again[0])
    assert "systemMessage" not in again[0]                   # the notice is once per repository


def test_a_slow_ranked_map_falls_back_to_the_cached_one(env, repo, tmp_path):
    e = dict(_env(env, tmp_path, slow=1), TE_REPOMAP_TIMEOUT="1")
    _, outs = _session(e, repo, "s1", ["Fix `parse_config`"])
    text = _ctx_text(outs[0])
    assert text.startswith("# Repository map") and "ranked toward []" in text


def test_codex_and_start_mode_get_the_cached_map_at_session_start(env, repo, tmp_path):
    start, outs = _session(_env(env, tmp_path), repo, "c1", ["Fix `x_y`"], host="codex")
    assert _ctx_text(start).startswith("# Repository map")
    assert all(_ctx_text(o) == "" for o in outs)
    start, outs = _session(_env(env, tmp_path, mode="start"), repo, "s9", ["Fix `x_y`"])
    assert _ctx_text(start).startswith("# Repository map") and _ctx_text(outs[0]) == ""


def test_shadow_and_off_inject_nothing(env, repo, tmp_path):
    _, outs = _session(dict(_env(env, tmp_path), TE_SHADOW="1"), repo, "s1", ["Fix `x_y`"])
    assert _ctx_text(outs[0]) == ""
    _, outs = _session(_env(env, tmp_path, mode="off"), repo, "s2", ["Fix `x_y`"])
    assert outs[0] == {}


def test_a_named_python_without_aider_is_reported_not_replaced(env, repo, tmp_path):
    e = _env(env, tmp_path, probe=1)
    start, outs = _session(e, repo, "s1", ["Fix `x_y`"])
    assert _ctx_text(start) == "" and _ctx_text(outs[0]) == ""     # nothing breaks
    from tokeneconomizer.plugin.context import LiveContext
    from tokeneconomizer.plugin.hosts import HOSTS
    st = repomap.read_state(LiveContext.build(HOSTS["claude"](), repo, e))
    assert "cannot import aider" in st["error"] and not st.get("map")


def test_prompt_identifiers():
    ids = repomap.prompt_idents("Fix `Model.save` so get_readonly_fields works on ModelAdmin")
    assert {"save", "get_readonly_fields", "ModelAdmin"} <= set(ids)


@pytest.mark.skipif(subprocess.run([sys.executable, "-c", "import aider.repomap"],
                                   capture_output=True).returncode != 0,
                    reason="aider is not installed")
def test_a_real_map_comes_from_tracked_files_and_leaves_the_repository_clean(tmp_path):
    root = tmp_path / "proj"
    (root / "pkg").mkdir(parents=True)
    (root / "pkg" / "core.py").write_text("class Engine:\n    def start(self):\n        pass\n")
    (root / "pkg" / "util.py").write_text("from pkg.core import Engine\n\ndef boot():\n"
                                          "    return Engine().start()\n")
    (root / "static").mkdir()
    (root / "static" / "big.min.js").write_text("function vendored(){}\n")
    for c in (["git", "init", "-q"], ["git", "add", "-A"]):
        subprocess.run(c, cwd=root, check=True)
    cache = tmp_path / "tags"
    out = subprocess.run([sys.executable, repomap.GEN, str(root), "512", "Engine", "--git",
                          "--cache", str(cache)], capture_output=True, text=True, timeout=300)
    assert out.returncode == 0, out.stderr[-400:]
    assert "pkg/core.py" in out.stdout and "Engine" in out.stdout
    assert "big.min.js" not in out.stdout                    # vendored assets are not mapped
    assert not any(n.startswith(".aider") for n in os.listdir(root))
    assert cache.exists()


def _repomap_context(tmp_path):
    return SimpleNamespace(store=Store(tmp_path / 'host'), repo=SimpleNamespace(root=str(tmp_path)),
                           config=LiveConfig(repomap_tokens=4096, repomap_python='chosen-python'), env={})

@pytest.mark.parametrize('python', [None, 'python'])
def test_failed_refresh_preserves_map_provenance(tmp_path, monkeypatch, python):
    ctx = _repomap_context(tmp_path)
    prior = dict(map='old map', chars=7, commit='old', tokens_budget=2048, python='old-python')
    repomap._write_state(ctx, prior)
    monkeypatch.setattr(repomap, 'head_commit', lambda root: 'new')
    monkeypatch.setattr(repomap, 'find_python', lambda ctx: python)
    monkeypatch.setattr(repomap, 'generate', lambda *args: ('', 'failed'))
    result = repomap.refresh(ctx)
    for key in prior:
        assert result[key] == prior[key]
    assert result['error']
    assert repomap.stale(ctx)


def test_prompt_does_not_run_cached_interpreter_after_explicit_change(tmp_path, monkeypatch):
    ctx = _repomap_context(tmp_path)
    repomap._write_state(ctx, dict(map='cached', python='old-python'))
    calls = []
    def generate(ctx, python, *args, **kwargs):
        calls.append(python)
        return '', 'unavailable'
    monkeypatch.setattr(repomap, 'generate', generate)
    block, how = repomap.for_prompt(ctx, 'Fix `parse_config`')
    assert calls == []
    assert how == 'cached'
    assert block.endswith('cached')


@pytest.mark.parametrize('use_git', [False, True])
def test_map_filters_directory_components_relative_to_repo(tmp_path, monkeypatch, capsys, use_git):
    # An excluded name outside the repository must not exclude the whole tree.
    repo = tmp_path / 'docs' / 'checkout'
    repo.mkdir(parents=True)
    for name in ['core.py', 'builders.py', 'distribution.py', 'docs_api/module.py', 'build/generated.py', 'docs/manual.py']:
        path = repo / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('def example(): pass\n')
    if use_git:
        subprocess.run(['git', 'init', '-q', str(repo)], check=True)
        subprocess.run(['git', '-C', str(repo), 'add', '.'], check=True)
    class RepoMap:
        def __init__(self, **kwargs):
            pass
        def get_repo_map(self, chat, files, **kwargs):
            return '\n'.join(sorted(os.path.relpath(p, repo) for p in files))
    monkeypatch.setitem(sys.modules, 'aider', SimpleNamespace())
    monkeypatch.setitem(sys.modules, 'aider.io', SimpleNamespace(InputOutput=lambda: None))
    monkeypatch.setitem(sys.modules, 'aider.models', SimpleNamespace(Model=lambda *args: None))
    monkeypatch.setitem(sys.modules, 'aider.repomap', SimpleNamespace(RepoMap=RepoMap))
    script = Path(__file__).resolve().parents[1] / 'tokeneconomizer/plugin/repomap_gen.py'
    monkeypatch.setattr(sys, 'argv', [str(script), str(repo), '100'] + (['--git'] if use_git else []))
    runpy.run_path(str(script), run_name='__main__')
    assert set(capsys.readouterr().out.splitlines()) == {'core.py', 'builders.py', 'distribution.py', os.path.join('docs_api', 'module.py')}
